boolean isPalindrome(int x) {
    if (x < 0) return false;
    int half = 0;
    while (x > half) {
        half = half * 10 + x % 10;
        x /= 10;
    }
    return x == half || x == half / 10;
}

int[] a = {4, 1, 4, 2, 1, 4, 2, 2};
Map<Integer, Integer> freq = new HashMap<>();
for (int x : a) freq.put(x, freq.getOrDefault(x, 0) + 1);
int best = -1, bestCount = 0;
for (int key : freq.keySet()) {
    int c = freq.get(key);
    if (c > bestCount || (c == bestCount && key < best)) {
        best = key;
        bestCount = c;
    }
}
System.out.println(best);

int countOdd(int[] a) {
    int count = 0;
    for (int x : a)
        if (x % 2 == 1) count++;
    return count;
}

